def digest(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def repo_root() -> Path:
    current = Path(__file__).resolve()
    # Script stored in FE root; require matching sibling BE.
    candidate = current.parent.parent
    if ((candidate / "Interplex_MES_FE").is_dir()
            and (candidate / "Interplex_MES_BE").is_dir()):
        return candidate
    raise RuntimeError("Updater must reside in Interplex_MES_FE, next to Interplex_MES_BE")


def load_assets():
    obj=json.loads(zlib.decompress(base64.b64decode(ASSET_B64)).decode("utf-8"))
    files={k:base64.b64decode(v['payload']) for k,v in obj['files'].items()}
    for name,b in files.items():
        if digest(b)!=obj['files'][name]['sha256']:
            raise RuntimeError("Corrupted embedded payload: " + name)
    return files


def git_branch(p: Path) -> str:
    try:
        r=subprocess.run(["git","-C",str(p),"rev-parse","--abbrev-ref","HEAD"],
              capture_output=True,text=True,timeout=4)
        return r.stdout.strip() if r.returncode==0 else "UNKNOWN"
    except Exception:
        return "UNKNOWN"


def source_checks(root: Path):
    issues=[]
    if sys.version_info < (3,9):
        issues.append(("REJECT",f"Python version {sys.version.split()[0]} unsupported (requires >=3.9)"))
    else:
        print(f"[PASS] Python {sys.version.split()[0]}")
    for side in ("Interplex_MES_FE","Interplex_MES_BE"):
        print(f"[INFO] {side} branch: {git_branch(root/side)}")
    docs=root/"Interplex_MES_FE/docs/mes_agent"
    if not docs.is_dir():
        issues.append(("REJECT", "Missing docs/mes_agent; install AgentDevKit first"))
    for rel,anchors in SOURCE_ANCHORS.items():
        p=root/rel
        if not p.is_file():
            issues.append(("REJECT",f"Missing required source: {rel}"));continue
        content=p.read_bytes()
        content_s=content.decode("utf-8",errors="replace")
        for a in anchors:
            if a not in content_s:
                issues.append(("REJECT",f"Critical anchor '{a}' missing in {rel}"))
        reference=BASELINE_SHA256.get(rel)
        if reference and digest(content)!=reference:
            # Existing code was updated after 2026-11-07 (e.g. RAW Phase C).
            # This is acceptable for audit-only installation when anchors exist.
            issues.append(("WARN",f"Source drift from 2026-11-07: {rel}; live auditor will re-index"))
    return issues


def plan_changes(root: Path, assets: dict):
    problems=[]
    changes=[]
    installed=0
    for rel, expected in assets.items():
        path=root/rel
        if path.exists():
            if not path.is_file():
                problems.append(f"Destination is not a file: {rel}")
            elif path.read_bytes()==expected:
                installed+=1
                changes.append((rel,"UNCHANGED",expected))
            else:
                problems.append(f"Existing release file differs, refusing overwrite: {rel}")
        else:
            changes.append((rel,"CREATE",expected))
    for rel,block in APPENDS.items():
        path=root/rel
        if not path.is_file():
            problems.append(f"Missing required Markdown: {rel}");continue
        original=path.read_bytes()
        s=original.decode('utf-8',errors='strict')
        mark_start='<!-- BEGIN MES2_RW_PHASE0_20261111 -->'
        mark_end='<!-- END MES2_RW_PHASE0_20261111 -->'
        if mark_start in s or mark_end in s:
            if mark_start in s and mark_end in s and block.strip() in s:
                installed+=1
                changes.append((rel,'UNCHANGED',original))
            else:
                problems.append(f"Partial/changed RW marker in {rel}")
        else:
            added=(('\n' if not s.endswith('\n') else '') + block).encode('utf-8')
            changes.append((rel,'APPEND',original+added))
    statuses=[status for _,status,_ in changes if status!='UNCHANGED']
    if installed and statuses and any(status=='UNCHANGED' for _,status,_ in changes if status=='UNCHANGED'):
        # Re-running on partially installed state is unsafe when new release files
        # already match but others have been deleted. Existing shared Markdown
        # alone is not a proof of partial release.
        new_have=sum(1 for rel,_,_ in changes if rel in assets and (root/rel).exists())
        if new_have>0 and new_have<len(assets):
            problems.append('Detected incomplete release installation (some release assets missing)')
    return changes,problems


def backup_root():
    return Path.home()/".ipth_mes_updater_backups"/RELEASE_ID


def apply(root: Path,changes):
    todo=[(rel,status,data) for rel,status,data in changes if status!='UNCHANGED']
    if not todo:
        print('[PASS] Release already installed; nothing to write')
        return 0
    target=backup_root()
    if target.exists():
        print('[REJECT] Backup for release already exists; refusing a second distinct install')
        return 2
    # Keep originals outside both Git repositories.
    target.mkdir(parents=True,exist_ok=False)
    bdir=target/'files';bdir.mkdir()
    manifest=[]
    for rel,status,data in todo:
        p=root/rel
        original=p.read_bytes() if p.exists() else None
        entry={'path':rel,'operation':status,'was_present':original is not None,
               'before_sha256':digest(original) if original is not None else None,
               'after_sha256':digest(data)}
        if original is not None:
            bp=bdir/rel;bp.parent.mkdir(parents=True,exist_ok=True);bp.write_bytes(original)
        manifest.append(entry)
    (target/'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    completed=[]
    try:
        for rel,status,data in todo:
            p=root/rel
            p.parent.mkdir(parents=True,exist_ok=True)
            fd,tmp=tempfile.mkstemp(prefix='.ipth_rw_',dir=p.parent)
            try:
                with os.fdopen(fd,'wb') as f:
                    f.write(data);f.flush();os.fsync(f.fileno())
                os.replace(tmp,p)
            finally:
                if os.path.exists(tmp):os.unlink(tmp)
            completed.append(rel)
        print('[PASS] RW Phase 0 tools + documentation installed. No runtime source/DB changes.')
        print('Backup:',target)
        return 0
    except Exception as exc:
        for rel in reversed(completed):
            entry=next(e for e in manifest if e['path']==rel)
            p=root/rel
            if entry['was_present']:
                p.write_bytes((bdir/rel).read_bytes())
            elif p.exists():p.unlink()
        archive=target.with_name(target.name+'_failed_'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
        try: target.rename(archive)
        except OSError: pass
        print('[REJECT] Failed to install; completed writes rolled back:',type(exc).__name__)
        return 2


def rollback(root: Path):
    target=backup_root()
    manifest_path=target/'manifest.json'
    if not manifest_path.is_file():
        print('[REJECT] No backup manifest for this release');return 2
    manifest=json.loads(manifest_path.read_text('utf-8'))
    for entry in manifest:
        p=root/entry['path']
        if not p.is_file() or digest(p.read_bytes())!=entry['after_sha256']:
            print('[REJECT] Refusing rollback of locally modified/missing file:',entry['path'])
            return 2
    for e in reversed(manifest):
        path=root/e['path']
        if e['was_present']:
            original=(target/'files'/e['path']).read_bytes()
            if digest(original)!=e['before_sha256']:
                print('[REJECT] Backup checksum mismatch:',e['path']);return 2
            path.write_bytes(original)
        else:path.unlink()
    archive=target.with_name(target.name+'_rolled_back_'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
    target.rename(archive)
    print('[PASS] Rollback restored original files; backup archived at',archive)
    return 0


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--scan',action='store_true')
    group.add_argument('--apply',action='store_true')
    group.add_argument('--rollback',action='store_true')
    args=parser.parse_args()
    try:
        root=repo_root()
        if args.rollback:return rollback(root)
        assets=load_assets()
        print(f'MES2 RW Phase 0 updater v{VERSION} | {RELEASE_ID}')
        issues=source_checks(root)
        changes,problems=plan_changes(root,assets)
        print('RELEASE FILES:')
        for rel,status,_ in changes: print(f'[{status:<9}] {rel}')
        print('MARKDOWN UPDATED:')
        for rel,status,_ in changes:
            if rel.endswith('.md') and status!='UNCHANGED': print('  +',rel)
        if problems:issues.extend(('REJECT',p) for p in problems)
        for severity,msg in issues: print(f'[{severity}] {msg}')
        if any(severity=='REJECT' for severity,_ in issues):
            print('VERDICT: REJECT — no changes permitted')
            return 2
        print('VERDICT: PASS'+(' WITH WARNINGS' if issues else '')+' — compatible for docs/auditor-only installation')
        if args.scan:
            print('SCAN is read-only: no files or SQL modified; DB metadata must be audited separately.')
            return 0
        return apply(root,changes)
    except Exception as e:
        print('VERDICT: REJECT — '+type(e).__name__+' (no credentials printed)')
        return 2


if __name__=='__main__':
    sys.exit(main())
